result.output:
400		case 0o100000:
401			if mode&0o111 != 0 {
402				return filemode.Executable
403			}
404			return filemode.Regular
405		case 0o120000:
406			return filemode.Symlink
407		default:
408			return filemode.Submodule
409		}
410	}
