412	// Encode transforms a Tree into a plumbing.EncodedObject.
413	//
414	// The tree is run through Tree.Validate before any bytes are written,
415	// so the encoder cannot produce a tree object containing components
416	// such as ".git", "..", control characters, HFS+/NTFS variants of
417	// ".git", null entry hashes, oversize names, mis-sorted or duplicate
418	// entries, or symlinks disguised as ".gitmodules"/".gitattributes"/
419	// ".gitignore"/".mailmap". Callers that need to emit such bytes for
420	// testing or recovery should write them directly via
421	// plumbing.EncodedObject rather than through this method.
422	func (t *Tree) Encode(o plumbing.EncodedObject) (err error) {
423		if err := t.Validate(); err != nil {
424			return err
425		}
426	
427		o.SetType(plumbing.TreeObject)
428		w, err := o.Writer()
429		if err != nil {
430			return err
431		}
432	
433		defer ioutil.CheckClose(w, &err)
434	
435		for _, entry := range t.Entries {
436			if _, err = fmt.Fprintf(w, "%o %s", entry.Mode, entry.Name); err != nil {
437				return err
438			}
439	
440			if _, err = w.Write([]byte{0x00}); err != nil {
441				return err
442			}
443	
444			if _, err = entry.Hash.WriteTo(w); err != nil {
445				return err
446			}
447		}
448	
449		return err
450	}
