452	// Validate reports whether the tree object obeys the same structural
453	// rules upstream Git's fsck_tree[1] enforces. It is the read-side
454	// counterpart to Tree.Encode's producer-side gate: Decode is permissive
455	// so that inspection and recovery tools can read trees with unusual
456	// entries, and callers that want fsck-shaped reporting call Validate.
457	//
458	// The returned error wraps ErrInvalidTree (and, where applicable,
459	// ErrEntriesNotSorted, ErrDuplicateEntry, or pathutil.ErrInvalidPath)
460	// so callers can match either the umbrella or specific rule with
461	// errors.Is. When multiple rules are violated they are reported
462	// together via errors.Join.
463	//
464	// Two fsck_tree warnings — zero-padded modes and the non-canonical
465	// 0100664 bits — are not surfaced here. Both rely on inspecting the
466	// original octal string from the wire, which canonicalTreeMode
467	// discards during Decode. Detecting them would require a parallel
468	// raw-mode field on TreeEntry; the structural rules below are the
469	// load-bearing ones for refusing malformed trees.
470	//
471	// [1]: https://github.com/git/git/blob/v2.54.0/fsck.c#L616-L800
472	func (t *Tree) Validate() error {
473		var errs []error
474		add := func(err error) {
475			errs = append(errs, fmt.Errorf("%w: %w", ErrInvalidTree, err))
476		}
477	
478		seen := make(map[string]struct{}, len(t.Entries))
479		var prevSortName string
480	
481		for i := range t.Entries {
482			e := &t.Entries[i]
483	
484			if e.Hash.IsZero() {
485				add(fmt.Errorf("entry %q points to null hash", e.Name))
486			}
487	
488			switch {
489			case e.Name == "":
490				add(errors.New("contains empty entry name"))
491			case strings.ContainsRune(e.Name, '/'):
492				add(fmt.Errorf("entry name %q contains a slash", e.Name))
493			default:
494				if err := pathutil.ValidTreePath(e.Name); err != nil {
495					add(err)
496				}
497				if _, dup := seen[e.Name]; dup {
498					add(fmt.Errorf("%w: %q", ErrDuplicateEntry, e.Name))
499				}
500				seen[e.Name] = struct{}{}
501	
502				if len(e.Name) > maxTreeEntryNameLen {
503					add(fmt.Errorf("entry name length %d exceeds %d", len(e.Name), maxTreeEntryNameLen))
504				}
505			}
506	
507			// Mode validation against the canonical set. Decode normalises
508			// the wire bytes via canonicalTreeMode, so this rule mainly
509			// catches programmatically-built trees with garbage modes;
510			// the zero-padded-mode and non-canonical-bit checks fsck_tree
511			// runs against the raw wire form are out of reach without
512			// retaining the original octal string.
513			if !isValidTreeMode(e.Mode) {
514				add(fmt.Errorf("entry %q has bad mode %o", e.Name, e.Mode))
515			}
516	
517			// Symlink-disguised metadata files. Mirrors the four FSCK_MSG_*
518			// _SYMLINK reports in fsck_tree.
519			if e.Mode == filemode.Symlink {
520				switch {
521				case pathutil.IsHFSDotGitmodules(e.Name) || pathutil.IsNTFSDotGitmodules(e.Name):
522					add(errors.New(".gitmodules is a symlink"))
523				case pathutil.IsHFSDotGitattributes(e.Name) || pathutil.IsNTFSDotGitattributes(e.Name):
524					add(errors.New(".gitattributes is a symlink"))
525				case pathutil.IsHFSDotGitignore(e.Name) || pathutil.IsNTFSDotGitignore(e.Name):
526					add(errors.New(".gitignore is a symlink"))
527				case pathutil.IsHFSDotMailmap(e.Name) || pathutil.IsNTFSDotMailmap(e.Name):
528					add(errors.New(".mailmap is a symlink"))
529				}
530			}
531	
532			sortName := treeEntrySortName(e)
533			if i > 0 && prevSortName > sortName {
534				add(ErrEntriesNotSorted)
535			}
536			prevSortName = sortName
537		}
538	
539		return errors.Join(errs...)
540	}
