542	// isValidTreeMode reports whether mode is one of the canonical tree
543	// modes upstream Git accepts in fsck_tree, including the non-canonical
544	// 0100664 that upstream tolerates outside --strict mode.
545	func isValidTreeMode(mode filemode.FileMode) bool {
546		switch mode {
547		case filemode.Regular,
548			filemode.Executable,
549			filemode.Symlink,
550			filemode.Dir,
551			filemode.Submodule,
552			filemode.Deprecated:
553			return true
554		}
555		return false
556	}
