21	// TreeChange represents a single file change within a tree.
22	// Use a nil Entry to indicate deletion.
23	type TreeChange struct {
24		// Path is the full path within the tree (e.g., "src/pkg/handler.go").
25		Path string
26		// Entry is the new tree entry. Nil means delete the file at Path.
27		Entry *object.TreeEntry
28	}
