185	// storeTree creates a git tree object from entries and stores it in the repo.
186	func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
187		tree := &object.Tree{Entries: entries}
188		obj := repo.Storer.NewEncodedObject()
189		if err := tree.Encode(obj); err != nil {
190			return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
191		}
192		hash, err := repo.Storer.SetEncodedObject(obj)
193		if err != nil {
194			return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
195		}
196		return hash, nil
197	}
