851	// FlattenTree recursively flattens a tree into a map of full paths to entries.
852	func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
853		for _, entry := range tree.Entries {
854			fullPath := entry.Name
855			if prefix != "" {
856				fullPath = prefix + "/" + entry.Name
857			}
858	
859			if entry.Mode == filemode.Dir {
860				// Recurse into subtree
861				subtree, err := repo.TreeObject(entry.Hash)
862				if err != nil {
863					return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
864				}
865				if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
866					return err
867				}
868			} else {
869				entries[fullPath] = object.TreeEntry{
870					Name: fullPath,
871					Mode: entry.Mode,
872					Hash: entry.Hash,
873				}
874			}
875		}
876		return nil
877	}
