1134	func filterGitIgnoredFiles(ctx context.Context, repo *git.Repository, files []string) []string {
1135		if len(files) == 0 {
1136			return files
1137		}
1138	
1139		wt, err := repo.Worktree()
1140		if err != nil {
1141			logging.Warn(logging.WithComponent(ctx, "checkpoint"),
1142				"failed to inspect worktree for gitignore filtering, excluding all files from checkpoint",
1143				slog.String("error", err.Error()))
1144			return nil
1145		}
1146		repoRoot := wt.Filesystem().Root()
1147	
1148		// Use git check-ignore to identify which files are ignored.
1149		// Pass files via stdin (-z for NUL-separated, --stdin) to handle special characters.
1150		// Use --no-index so even tracked files that still match ignore rules are filtered.
1151		cmd := exec.CommandContext(ctx, "git", "check-ignore", "--no-index", "-z", "--stdin")
1152		cmd.Dir = repoRoot
1153		cmd.Stdin = strings.NewReader(strings.Join(files, "\x00") + "\x00")
1154	
1155		output, err := cmd.Output()
1156		if err != nil {
1157			exitErr := &exec.ExitError{}
1158			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1159				// Exit code 1 means no files are ignored — all files are safe.
1160				return files
1161			}
1162			// Any other failure (exit 128, git not found, etc.): fail closed.
1163			// A missing checkpoint is better than leaked secrets.
1164			logging.Warn(logging.WithComponent(ctx, "checkpoint"),
1165				"git check-ignore failed, excluding all files from checkpoint",
1166				slog.String("error", err.Error()))
1167			return nil
1168		}
1169	
1170		// Parse NUL-separated output of ignored file names
1171		ignored := make(map[string]struct{})
1172		for _, name := range strings.Split(string(output), "\x00") {
1173			if name != "" {
1174				ignored[name] = struct{}{}
1175			}
1176		}
1177	
1178		// Filter: keep only files that are not ignored
1179		var kept []string
1180		filteredCount := 0
1181		for _, file := range files {
1182			if _, isIgnored := ignored[file]; isIgnored {
1183				filteredCount++
1184				continue
1185			}
1186			kept = append(kept, file)
1187		}
1188	
1189		if filteredCount > 0 {
1190			logging.Debug(logging.WithComponent(ctx, "checkpoint"),
1191				"filtered gitignored files from checkpoint",
1192				slog.Int("count", filteredCount))
1193		}
1194	
1195		return kept
1196	}
