1210		cleanPath := filepath.Clean(filepath.FromSlash(relPath))
1211		if paths.IsInfrastructurePath(cleanPath) {
1212			return true
1213		}
1214		for _, file := range agent.AllProtectedFiles() {
1215			if paths.Equal(cleanPath, file) {
1216				return true
1217			}
1218		}
1219		for _, dir := range agent.AllProtectedDirs() {
1220			if paths.IsProtectedSubpath(filepath.Clean(filepath.FromSlash(dir)), cleanPath) {
