1227	// collectChangedFiles returns all changed files from git status for the first checkpoint.
1228	//
1229	// For the first checkpoint, we need to capture:
1230	// - Modified tracked files (user's uncommitted changes)
1231	// - Untracked non-ignored files (new files not yet added to git)
1232	// - Renamed/copied files (both source removal and destination)
1233	// - Deleted files (to exclude from checkpoint tree)
1234	//
1235	// The base tree from HEAD already contains all unchanged tracked files.
1236	//
1237	// Uses `git status --porcelain -z` for reliable parsing of filenames with special characters.
1238	func collectChangedFiles(ctx context.Context, repo *git.Repository) (changedFilesResult, error) {
1239		// Get worktree root directory for running git command
1240		wt, err := repo.Worktree()
1241		if err != nil {
1242			return changedFilesResult{}, fmt.Errorf("failed to get worktree: %w", err)
1243		}
1244		repoRoot := wt.Filesystem().Root()
1245	
1246		// Use -z for NUL-separated output (handles quoted filenames with spaces/special chars)
1247		// Use -uall to list individual untracked files instead of collapsed directories.
1248		// Note: CLAUDE.md warns against -uall for user-facing display, but we need the full list
1249		// for checkpointing.
1250		cmd := exec.CommandContext(ctx, "git", "status", "--porcelain", "-z", "-uall")
1251		cmd.Dir = repoRoot
1252		output, err := cmd.Output()
1253		if err != nil {
1254			return changedFilesResult{}, fmt.Errorf("failed to get git status in %s: %w", repoRoot, err)
1255		}
1256	
1257		changedSeen := make(map[string]struct{})
1258		deletedSeen := make(map[string]struct{})
1259	
1260		// Parse NUL-separated output
1261		// Format: XY filename\0 (for most entries)
1262		// For renames/copies: XY newname\0oldname\0
1263		entries := strings.Split(string(output), "\x00")
1264	
1265		for i := 0; i < len(entries); i++ {
1266			entry := entries[i]
1267			if len(entry) < 3 {
1268				continue
1269			}
1270	
1271			// git status --porcelain format: XY filename
1272			// X = staging status, Y = worktree status
1273			staging := entry[0]
1274			wtStatus := entry[1]
1275			filename := entry[3:] // No TrimSpace needed with -z format
1276	
1277			// Handle R/C (rename/copy) first - they have a second entry we must skip
1278			// even if the new filename is a protected path
1279			if staging == 'R' || staging == 'C' {
1280				// Renamed or copied: current entry is new name, next entry is old name
1281				if !isProtectedCheckpointPath(filename) {
1282					changedSeen[filename] = struct{}{}
1283				}
1284				// The old name follows as the next NUL-separated entry - must always skip it
1285				if i+1 < len(entries) && entries[i+1] != "" {
1286					oldName := entries[i+1]
1287					if staging == 'R' && !isProtectedCheckpointPath(oldName) {
1288						// For renames, old file is effectively deleted
1289						deletedSeen[oldName] = struct{}{}
1290					}
1291					i++ // Skip the old name entry
1292				}
1293				continue
1294			}
1295	
1296			// Skip .entire and agent-protected dirs/files for non-R/C entries
1297			if isProtectedCheckpointPath(filename) {
1298				continue
1299			}
1300	
1301			// Handle different status codes
1302			switch {
1303			case staging == 'D' || wtStatus == 'D':
1304				// Deleted file - track separately
1305				deletedSeen[filename] = struct{}{}
1306	
1307			case wtStatus == 'M' || wtStatus == 'A':
1308				// Modified or added in worktree
1309				changedSeen[filename] = struct{}{}
1310	
1311			case staging == '?' && wtStatus == '?':
1312				// Untracked file
1313				changedSeen[filename] = struct{}{}

