266		repo, err := openRepository(ctx)
267		if err != nil {
268			return nil, fmt.Errorf("failed to open repository: %w", err)
269		}
270		defer repo.Close()
271	
272		worktree, err := repo.Worktree()
273		if err != nil {
274			return nil, fmt.Errorf("failed to get worktree: %w", err)
275		}
276	
277		status, err := worktree.Status()
278		if err != nil {
279			return nil, fmt.Errorf("failed to get status: %w", err)
280		}
281	
282		// Build set of pre-existing untracked files for quick lookup
283		var preExisting map[string]bool
284		if previouslyUntracked != nil {
285			preExisting = make(map[string]bool, len(previouslyUntracked))
286			for _, f := range previouslyUntracked {
287				preExisting[f] = true
288			}
289		}
290	
291		var changes FileChanges
292		for file, st := range status {
293			if shouldIgnoreSessionTrackingPath(file) {
294				continue
295			}
296	
297			switch {
298			case st.Worktree == git.Untracked:
299				if preExisting != nil {
300					if !preExisting[file] {
301						changes.New = append(changes.New, file)
302					}
303				} else {
304					changes.New = append(changes.New, file)
305				}
306			case st.Worktree == git.Deleted || st.Staging == git.Deleted:
307				changes.Deleted = append(changes.Deleted, file)
308			case st.Worktree == git.Modified || st.Staging == git.Modified ||
309				st.Worktree == git.Added || st.Staging == git.Added:
310				changes.Modified = append(changes.Modified, file)
311			}
312		}
313	
314		return &changes, nil
315	}
