317	// filterToUncommittedFiles removes files from the list that are already committed to HEAD
318	// with matching content. This prevents re-adding files that an agent committed mid-turn
319	// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
320	// HEAD or with different content in the working tree are kept. Fails open: if any git
321	// operation errors, returns the original list unchanged.
322	func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
323		if len(files) == 0 {
324			return files
325		}
326	
327		repo, err := openRepository(ctx)
328		if err != nil {
329			return files // fail open
330		}
331		defer repo.Close()
332	
333		head, err := repo.Head()
334		if err != nil {
335			return files // fail open (empty repo, detached HEAD, etc.)
336		}
337	
338		commit, err := repo.CommitObject(head.Hash())
339		if err != nil {
340			return files // fail open
341		}
342	
343		headTree, err := commit.Tree()
344		if err != nil {
345			return files // fail open
346		}
347	
348		logCtx := logging.WithComponent(ctx, "filter-uncommitted")
349	
350		var result []string
351		for _, relPath := range files {
352			headFile, err := headTree.File(relPath)
353			if err != nil {
354				// File not in HEAD — it's uncommitted
355				logging.Debug(logCtx, "file not in HEAD tree, keeping",
356					slog.String("file", relPath),
357					slog.String("error", err.Error()))
358				result = append(result, relPath)
359				continue
360			}
361	
362			// File is in HEAD — compare content with working tree
363			absPath := filepath.Join(repoRoot, relPath)
364			workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
365			if err != nil {
366				// Can't read working tree file (deleted?) — keep it
367				result = append(result, relPath)
368				continue
369			}
370	
371			headContent, err := headFile.Contents()
372			if err != nil {
373				result = append(result, relPath)
374				continue
375			}
376	
377			if string(workingContent) != headContent {
378				// Working tree differs from HEAD — uncommitted changes
379				result = append(result, relPath)
380			}
381			// else: content matches HEAD — already committed, skip
382		}
383	
384		return result
385	}
