404	// mergeUnique appends elements from extra into base, skipping duplicates already in base.
405	func mergeUnique(base, extra []string) []string {
406		if len(extra) == 0 {
407			return base
408		}
409		seen := make(map[string]bool, len(base))
410		for _, s := range base {
411			seen[s] = true
412		}
413		for _, s := range extra {
414			if !seen[s] {
415				seen[s] = true
416				base = append(base, s)
417			}
418		}
419		return base
